    slots: ['hero'],
    provider: {
      suppressOn: QUIET_CHECKOUT,
      toastEngagement: { delayMs: 6000, scrollDepth: 0.25 },
    },
    promotions: finish(
      {
        bar: record({
          id: 'bar',
          placement: 'bar',
          tone: 'brand',
          eyebrow: 'Spring sale',
          title: 'Up to 30% off linen until Sunday',
          cta: { label: 'Shop linen', href: r.product },
          startsAt: startsAt - DAY,
          endsAt: saleEnds,
