          cta: { label: 'Find a store', href: r.shop },
          include: [r.home, r.shop],
          startsAt: startsAt - 2 * DAY,
          endsAt: startsAt + 12 * DAY,
          priority: 40,
          dismiss: { mode: 'session' },
          campaign: 'repairs',
          translations: tr({
            fr: {
              eyebrow: 'Semaine réparation',
              title: 'Réparation gratuite de toute pièce',
