            hi: { eyebrow: 'मरम्मत सप्ताह', title: 'किसी भी पीस की मुफ़्त मरम्मत' },
            ar: { eyebrow: 'أسبوع الإصلاح', title: 'إصلاح مجاني لأي قطعة' },
          }),
        }),
        members: record({
          id: 'members',
          placement: 'side',
          eyebrow: 'Members',
          title: 'Free repairs and returns, for life',
          body: 'Join free with your email. Members also get early access to every sale.',
          media: images[2],
          cta: { label: 'Join free', href: r.shop },
          startsAt: startsAt - DAY,
          endsAt: startsAt + 60 * DAY,
          priority: 40,
          dismiss: { mode: 'days', days: 30 },
          // An invitation to join is noise for someone who already has.
          audience: { exclude: ['member'] },
          campaign: 'members',
          translations: tr({
            fr: {
              eyebrow: 'Membres',
              title: 'Réparations et retours gratuits, à vie',
              ctaLabel: 'Rejoindre',
            },
            de: {
              eyebrow: 'Mitglieder',
              title: 'Reparaturen und Rücksendungen, lebenslang gratis',
              ctaLabel: 'Kostenlos beitreten',
            },
            ja: {
              eyebrow: 'メンバー',
              title: '修理と返品がずっと無料',
              ctaLabel: '無料で参加',
            },
            hi: {
              eyebrow: 'सदस्य',
              title: 'जीवन भर मुफ़्त मरम्मत और वापसी',
              ctaLabel: 'मुफ़्त जुड़ें',
            },
            ar: {
              eyebrow: 'الأعضاء',
              title: 'إصلاح وإرجاع مجانيان مدى الحياة',
              ctaLabel: 'انضم مجانًا',
            },
          }),
        }),
      },
      { id, overrides },
    ),
  }
}

import {
  DAY,
  QUIET_CHECKOUT,
  SAMPLE_PAGES,
  finish,
  record,
  tr,
  type KitOptions,
  type PromotionKit,
} from './promotion-kit'

type LaunchRoutes = {
  home: string
  pricing: string
  docs: string
  changelog: string
  event: string
}

/**
 * A launch week for a software product:
 *
 * - `pill`: "New: team workspaces" above the hero (`announcement` slot).
 * - `bar`: one line per day of the launch, with a countdown to Friday.
 * - `offer`: a toast with a code on pricing and docs, a separate campaign.
 * - `keynote`: a dialog scheduled two days in, with a gallery of the agenda.
 *   It waits for engagement, and the daily budget keeps it from stacking on
 *   the toast.
 */
export function productLaunchKit({
  startsAt = Date.now(),
  id = 'launch',
  routes = {},
  overrides,
  images = SAMPLE_PAGES,
}: KitOptions<LaunchRoutes> = {}): PromotionKit {
  const r: LaunchRoutes = {
    home: '/',
    pricing: '/pricing',
    docs: '/docs',
    changelog: '/changelog',
    event: 'https://example.com/keynote',
    ...routes,
  }
  return {
    slots: ['announcement', 'share'],
    provider: {
      suppressOn: QUIET_CHECKOUT,
      dialogEngagement: { delayMs: 12_000, scrollDepth: 0.4 },
    },
    promotions: finish(
      {
        pill: record({
          id: 'pill',
          placement: 'card',
          slot: 'announcement',
          eyebrow: 'New',
          title: 'Team workspaces are here',
          cta: { label: 'Read the changelog', href: r.changelog },
          startsAt: startsAt - DAY,
          endsAt: startsAt + 14 * DAY,
          campaign: 'week',
